const act1 = $('Generate Act 1').item.json.text;
const act2 = $('Generate Act 2').item.json.text;
const act3 = $('Generate Act 3').item.json.text;

const fullScript = `${act1}\n\n---\n\n${act2}\n\n---\n\n${act3}`;

return {
  json: {
    text: fullScript
  }
};

const outline = $('Format Outline').item.json.outline;
const fullScript = $('Merge Scripts').item.json.text;

// Recupera case_name dal nodo "Prepare URL"
const caseName = $('Prepare URL').item.json.case_name;
const episodeNumber = outline.episode_number;
const totalEpisodes = outline.total_episodes;

return {
  json: {
    // Identificatori
    case_name: caseName,
    episode_number: episodeNumber,
    total_episodes: totalEpisodes,
    episode_title: outline.episode_title,

    // URLs
    wiki_url: $('Prepare URL').item.json.wiki_url,

    // Contenuti
    outline: outline,
    full_script: fullScript,

    // Metadata
    word_count: fullScript.split(/\s+/).length,
    estimated_duration_minutes: Math.round(fullScript.split(/\s+/).length / 150),
    generated_at: new Date().toISOString(),

    // Pricing info
    is_final_episode: episodeNumber === totalEpisodes,

    // Export
    filename_suggestion: `${caseName.replace(/ /g, '_')}_EP${episodeNumber}_of_${totalEpisodes}_script.txt`
  }
};

const caseName = $input.item.json.body.case_name;
const episodeNumber = $input.item.json.body.episode_number || 1;
const totalEpisodes = $input.item.json.body.total_episodes || 3;

const wikiUrl = `https://en.wikipedia.org/wiki/${caseName.replace(/ /g, '_')}`;

return {
  json: {
    case_name: caseName,
    episode_number: episodeNumber,
    total_episodes: totalEpisodes,
    wiki_url: wikiUrl
  }
};

const html = $input.item.json.data;

// Rimuove tag HTML basilari (regex semplice per MVP)
const text = html
  .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
  .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
  .replace(/<[^>]+>/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// Prendi primi 3000 caratteri
const summary = text.substring(0, 3000);

return {
  json: {
    case_name: $input.item.json.case_name,
    wiki_url: $input.item.json.wiki_url,
    raw_text: summary
  }
};

let outline;
try {
  const aiResponse = $input.item.json.text;
  const cleanJson = aiResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  outline = JSON.parse(cleanJson);
} catch (error) {
  return {
    json: {
      error: "Failed to parse AI response",
      raw_response: $input.item.json.text
    }
  };
}

// FORZA il numero episodio corretto dall'input originale
const correctEpisodeNumber = $('Prepare URL').item.json.episode_number;
outline.episode_number = correctEpisodeNumber;

return {
  json: {
    case_name: $('Extract Text').item.json.case_name,
    wiki_url: $('Extract Text').item.json.wiki_url,
    outline: outline,
    generated_at: new Date().toISOString()
  }
};

const data = $('Generate Full Script - JSON').item.json;
const caseData = $input.item.json; // Output di Save Case

// Debug: verifica cosa arriva da Save Case
console.log('Case Data:', JSON.stringify(caseData));

// Prendi l'ID del caso (gestisce diversi formati di output)
const caseId = caseData.id ?? caseData[0]?.id ?? 0;

// Crea lo slug
const slug = data.case_name.toLowerCase().replace(/ /g, '-').replace(/_/g, '-');

return {
  json: {
    case_id: caseId,
    slug: slug,
    case_name: data.case_name,
    episode_number: data.episode_number,
    episode_title: data.episode_title,
    outline: data.outline,
    full_script: data.full_script,
    word_count: data.word_count,
    estimated_duration_minutes: data.estimated_duration_minutes,
    filename: data.filename_suggestion,
    is_final_episode: data.is_final_episode,
    price_cents: 499
  }
};
